        public string PartyPersonKey(Transform person){var visiting=person.GetComponent<HomePartyGuestView>();if(visiting!=null)return visiting.Data.key;if(person==forestFriend)return "friend:小禾";var style=person.GetComponent<CastleGirlStyle>();if(style!=null)return "castle-child:"+style.StyleId;var family=person.GetComponent<SkyResidentInfo>();if(family!=null)return "family:"+World.Region+":"+family.Owner.name+":"+family.Index;var v=person.GetComponent<Villager>();if(v!=null)return "villager:"+World.Region+":"+v.ResidentId;var c=person.GetComponent<CommunityCitizen>();if(c!=null)return "citizen:"+World.Region+":"+person.name+":"+Mathf.RoundToInt(c.Home.x)+":"+Mathf.RoundToInt(c.Home.z);var age=person.GetComponent<PlanetCitizenAge>();if(age!=null)return "planet:"+age.CitizenId;return "person:"+World.Region+":"+person.name+":"+Mathf.RoundToInt(person.position.x)+":"+Mathf.RoundToInt(person.position.z);}
        public bool AcceptHomePartyInvitation(Transform person)
        {
            if(person==null||HomePartyGuests.Count>=100)return false;string key=PartyPersonKey(person);if(HomePartyGuests.Exists(p=>p.key==key)){partyReply="我已经收到邀请了，今天晚上来参加你的派对。";return true;}
            var style=person.GetComponent<CastleGirlStyle>();var family=person.GetComponent<SkyResidentInfo>();var citizen=person.GetComponent<CommunityCitizen>();var guest=new HomePartyGuest{key=key,name=person.name,region=World.Region,kind=style!=null?1:family!=null&&family.Child?2:family!=null?3:person==forestFriend?4:person.GetComponent<Villager>()!=null||citizen!=null?0:5,style=style==null?0:style.StyleId,role=citizen==null?"宾客":citizen.Role,color=Color.HSVToRGB((HomePartyGuests.Count*.19f)%1,.35f,.78f)};HomePartyGuests.Add(guest);EnsurePartyKit();partyReply="好的，今天晚上我来参加你的派对。";return true;
        }
        public void EnsurePartyKit(){if(partyKitVersion<1){int[] kit={2,4,1,2,8};for(int i=0;i<5;i++)PartyStock[i]=Mathf.Max(PartyStock[i],kit[i]);}if(partyKitVersion<2){PartyStock[5]=Mathf.Max(1,PartyStock[5]);PartyStock[6]=Mathf.Max(1,PartyStock[6]);}partyKitVersion=2;}
        public bool OpenPartyBag(){if(CompanionReturnBlocked||PhoneOpen||StickerOpen)return false;EnsurePartyKit();partyBag=true;inventoryOpen=false;SetPaused(true);return true;}
        public void ClosePartyBag(){partyBag=false;SetPaused(false);}
        public bool TakePartyItem(int kind){if(kind<0||kind>=PartyStock.Length||PartyStock[kind]<1){Notice="这件用品已摆完；左键看着旧摆放可收回。";return false;}PutAwayPartyItem();partyHeld=kind;partyHand=new GameObject("手中"+PartyItemNames[kind]).transform;partyHand.SetParent(Player.View.transform,false);partyHand.localPosition=new Vector3(.34f,-.35f,.68f);partyHand.localScale=Vector3.one*.25f;BuildPartyPropArt(partyHand,kind);foreach(var t in partyHand.GetComponentsInChildren<Transform>())t.gameObject.layer=2;partyBag=false;SetPaused(false);Notice="拿着"+PartyItemNames[kind]+"。看着自己家里的地面，右键摆放；G使用，左键收回。";return true;}
        public void PutAwayPartyItem(){partyHeld=-1;if(partyHand!=null)Destroy(partyHand.gameObject);partyHand=null;}
        bool PartyPlaceFromView(){if(partyHeld<0)return false;if(!RayFromView(out var hit,6)){Notice="请看着自己家里6米内的地面。";return true;}if(hit.normal.y<.7f){Notice="派对用品需要摆在平整地面上。";return true;}return PlacePartyProp(partyHeld,hit.point+Vector3.up*.04f,Player.transform.eulerAngles.y);}
        OwnedHome PartyHouseAt(Vector3 p){foreach(var h in OwnedHomes)if(h.region==World.Region&&((h.realm&&InVoidRealms)||!h.realm&&!InVoidRealms)){if(p.x>h.x&&p.x<h.x+10&&p.z>h.z&&p.z<h.z+10&&p.y>=(h.deepBaseVersion==1?DeepFloorY(h,9):h.y-5)&&p.y<h.y+10)return h;if(h.partyHallVersion==1&&p.x>h.partyX&&p.x<h.partyX+h.partyW&&p.z>h.partyZ&&p.z<h.partyZ+h.partyD&&Mathf.Abs(p.y-(h.y+2))<2)return h;}return null;}
        static Vector3 PartyPropSize(int kind)=>kind==5?new Vector3(2.8f,3.4f,2):kind==6?new Vector3(1.8f,2.5f,4):kind==2?new Vector3(3,.5f,2.3f):kind==3?new Vector3(2.4f,1.2f,1.5f):kind==4?new Vector3(.7f,2.8f,.7f):new Vector3(.8f,1.5f,.7f);
        public bool PlacePartyProp(int kind,Vector3 p,float yaw=0)
        {
            var h=PartyHouseAt(p);if(kind<0||kind>=PartyStock.Length||PartyStock[kind]<1||h==null||saveBlocked||Paused){Notice="请在自己的房屋、派对厅或密室里摆放。";return false;}var size=PartyPropSize(kind);Vector3 center=p+Vector3.up*size.y/2;foreach(var c in Physics.OverlapBox(center,size*.45f,Quaternion.Euler(0,yaw,0),~(1<<2),QueryTriggerInteraction.Ignore))if(c!=Player.Body&&c.bounds.max.y>p.y+.15f){Notice="这里有家具或人物，换一个空位置。";return false;}if(new Bounds(center,size).Intersects(Player.Body.bounds)){Notice="先退后一点，不能把道具摆进身体里。";return false;}int id=1;foreach(var prop in HomePartyProps)id=Mathf.Max(id,prop.id+1);var record=new HomePartyProp{id=id,kind=kind,region=World.Region,home=HomeKey(h),realm=h.realm,position=p,yaw=yaw,on=kind==1};HomePartyProps.Add(record);PartyStock[kind]--;string prior=partyHome;if(p.y>=h.y)partyHome=HomeKey(h);if(!SavePartyState()){HomePartyProps.Remove(record);PartyStock[kind]++;partyHome=prior;return false;}BuildHomeParty();Notice=PartyItemNames[kind]+"已经摆好了，位置会保存。";return true;
        }
        public bool RemovePartyProp(int id){var prop=HomePartyProps.Find(p=>p.id==id);if(prop==null||homePartyRunning||PartyStock[prop.kind]>=9999)return false;HomePartyProps.Remove(prop);PartyStock[prop.kind]++;if(!SavePartyState()){HomePartyProps.Add(prop);PartyStock[prop.kind]--;return false;}BuildHomeParty();Notice="派对用品已收回书包。";return true;}
        bool SavePartyState(){if(saveBlocked)return false;try{WorldSave.Write(WorldSave.Capture(World,Player,Inventory,Selected),WorldSave.PathName);return true;}catch(Exception){Notice="派对修改没有保存，已恢复。";return false;}}
        public bool StartHomeParty()
        {
            var h=PartyHome();if(homePartyRunning)return true;if(!IsNight||h==null||h.region!=World.Region||h.partyHallVersion!=1||HomePartyGuests.Count==0)return false;if(!PrepareSmallHousePartyRoute(h))return false;bool stage=false,speaker=false;foreach(var p in HomePartyProps)if(p.home==partyHome&&InPartyHall(h,p.position)){stage|=p.kind==2;speaker|=p.kind==0;}if(!stage||!speaker){Notice="请把舞台和音响摆在扩建的大房间里，再按N天黑。";BuildHomeParty();return false;}var oldOn=new bool[HomePartyProps.Count];for(int i=0;i<oldOn.Length;i++)oldOn[i]=HomePartyProps[i].on;homePartyRunning=true;foreach(var p in HomePartyProps)if(p.home==partyHome)p.on=true;if(!SavePartyState()){homePartyRunning=false;for(int i=0;i<oldOn.Length;i++)HomePartyProps[i].on=oldOn[i];return false;}BuildHomeParty();Notice="飞车停原小屋门口，宾客先进入小屋，再到连接的大房间参加派对。";return true;
        }
        public void StopHomeParty(){if(!homePartyRunning)return;homePartyRunning=false;foreach(var guest in HomePartyGuests)guest.arrived=false;SavePartyState();BuildHomeParty();Notice="白天到了，派对结束。用品与宾客名单仍保存，下次天黑还能再聚。";}
        void ResetHomePartyModels(){StopPartyRide();partyTalker=null;foreach(var p in partyHiddenPeople)if(p!=null)p.SetActive(true);partyHiddenPeople.Clear();if(partyRoot!=null){partyRoot.gameObject.SetActive(false);Destroy(partyRoot.gameObject);}partyRoot=null;}
        void BuildHomeParty()
        {
            ResetHomePartyModels();partyReservedSeats.Clear();partyRoot=new GameObject("家里可保存的派对用品与宾客").transform;partyRoot.SetParent(villagePeople.transform,false);
            foreach(var p in HomePartyProps)if(p.region==World.Region){var root=new GameObject(PartyItemNames[p.kind]+" "+p.id).transform;root.SetParent(partyRoot,false);root.position=p.position;root.rotation=Quaternion.Euler(0,p.yaw,0);BuildPartyPropArt(root,p.kind);var view=root.gameObject.AddComponent<HomePartyPropView>();view.Data=p;if(p.kind==0){view.Speaker=root.gameObject.AddComponent<AudioSource>();view.Speaker.clip=EnsurePartyMusic();view.Speaker.loop=true;view.Speaker.volume=.12f;view.Speaker.spatialBlend=.65f;view.Speaker.maxDistance=25;if(p.on&&homePartyRunning)view.Speaker.Play();}if(p.kind==1){view.Lamp=root.gameObject.AddComponent<Light>();view.Lamp.type=LightType.Point;view.Lamp.range=8;view.Lamp.intensity=.7f;}}
            foreach(var home in OwnedHomes)if(home.region==World.Region&&home.partyHallVersion==1){Vector3 doorway=PartyDoor(home)+PartyOutward(home)*1.35f;var art=partyRoot.gameObject.AddComponent<RoyalArt>();art.Piece("派对厅门外半格踏步",new Vector3(doorway.x,home.y+1.25f,doorway.z),new Vector3(3,.5f,2),new Color(.7f,.52f,.35f),PrimitiveType.Cube,true);PlaceSign(partyRoot,"我家的大派对厅 · N天黑迎接宾客",new Vector3(home.partyX+home.partyW/2f,home.y+5,home.partyZ+home.partyD-.5f));}
            foreach(var home in OwnedHomes)if(home.region==World.Region&&home.partyHallVersion==1){var art=partyRoot.gameObject.AddComponent<RoyalArt>();Vector3 landing=SmallHousePartyLanding(home);landing.y=home.y+1.95f;art.Piece("原小屋门口的飞车落客平台",landing,new Vector3(8,.2f,7),new Color(.69f,.51f,.36f),PrimitiveType.Cube,true);}
            foreach(var home in OwnedHomes)if(home.region==World.Region&&home.partyHallVersion==1)for(int i=0;i<4;i++){var lamp=new GameObject("派对厅暖灯").AddComponent<Light>();lamp.transform.SetParent(partyRoot,false);lamp.transform.position=new Vector3(home.partyX+4+i%2*(home.partyW-8),home.y+6,home.partyZ+4+i/2*(home.partyD-8));lamp.type=LightType.Point;lamp.range=13;lamp.intensity=1.4f;lamp.color=new Color(1,.84f,.69f);}
            var h=PartyHome();if(!homePartyRunning||h==null||h.region!=World.Region)return;OpenSmallHouseForGuests(h);Vector3 centre=new Vector3(h.partyX+h.partyW/2f,h.y+2.05f,h.partyZ+h.partyD/2f);int n=0;
            foreach(var guest in HomePartyGuests){RoyalArt person=guest.kind==1?CastleGirlStyle.Make(partyRoot,guest.style):guest.kind==4?RoyalArt.ForestFriend(partyRoot):guest.kind==5?RoyalArt.Girl(partyRoot,false,false):MakeCommunityPerson(partyRoot,guest.name,centre,guest.color,guest.role);
                if(guest.kind==2)person.transform.localScale=Vector3.one*.7f;if(guest.kind==3)foreach(var r in person.GetComponentsInChildren<Renderer>())if(r.name=="头发")r.sharedMaterial.color=new Color(.84f,.85f,.87f);var citizen=person.GetComponent<CommunityCitizen>();if(citizen!=null)citizen.enabled=false;
                var view=person.gameObject.AddComponent<HomePartyGuestView>();view.Data=guest;view.Game=this;view.Seat=FindPartyGuestSpot(centre,n);view.Door=SmallHousePartyDoor(h);view.Landing=SmallHousePartyLanding(h)+Vector3.right*((n%3-1)*1.5f)+Vector3.back*(n/3*1.2f);view.From=view.Landing+new Vector3((n%2==0?-1:1)*12,22,-14);view.Age=-n*.8f;view.Phase=guest.arrived?2:0;person.transform.position=guest.arrived?view.Seat:view.From;NpcNavigation.Ensure(person.transform);
                if(h.partyDir<2){float lane=view.Seat.x<centre.x?h.partyX+1.6f:h.partyX+h.partyW-1.6f;view.RouteA=new Vector3(lane,centre.y,view.Door.z+(h.partyDir==0?-1:1));view.RouteB=new Vector3(lane,centre.y,Mathf.Clamp(view.Seat.z+3,h.partyZ+1.6f,h.partyZ+h.partyD-1.6f));}else{float lane=view.Seat.z<centre.z?h.partyZ+1.6f:h.partyZ+h.partyD-1.6f;view.RouteA=new Vector3(view.Door.x+(h.partyDir==2?-1:1),centre.y,lane);view.RouteB=new Vector3(Mathf.Clamp(view.Seat.x+3,h.partyX+1.6f,h.partyX+h.partyW-1.6f),centre.y,lane);}
                if(h.partyDir<2)view.RouteA.z=h.partyDir==0?h.partyZ+2:h.partyZ+h.partyD-2;else view.RouteA.x=h.partyDir==2?h.partyX+2:h.partyX+h.partyW-2;
                view.Route=BuildSmallHouseGuestRoute(h,view.RouteA,view.RouteB,view.Seat);
                if(!guest.arrived){view.Car=BuildPartyFlyingCar(partyRoot,view.From,guest.color);person.transform.position=view.From+Vector3.up*.35f;}else person.transform.position=view.Seat;
                foreach(var source in FindObjectsByType<NpcNavigation>())HidePartyOriginal(source.transform,guest.key);foreach(var source in FindObjectsByType<Villager>())HidePartyOriginal(source.transform,guest.key);foreach(var source in FindObjectsByType<SkyResidentInfo>())HidePartyOriginal(source.transform,guest.key);n++;}
        }
        void HidePartyOriginal(Transform source,string key){if(source.GetComponent<HomePartyGuestView>()!=null||!source.gameObject.activeSelf||PartyPersonKey(source)!=key)return;partyHiddenPeople.Add(source.gameObject);source.gameObject.SetActive(false);}
        Vector3 FindPartyGuestSpot(Vector3 c,int n){var home=PartyHome();int nx=Mathf.Max(3,Mathf.FloorToInt((home.partyW-3)/1.2f)),nz=Mathf.Max(3,Mathf.FloorToInt((home.partyD-3)/1.2f));for(int k=0;k<nx*nz;k++){int slot=(n+k)%(nx*nz);Vector3 p=c+new Vector3((slot%nx-(nx-1)*.5f)*1.2f,0,(slot/nx-(nz-1)*.5f)*1.2f);bool clear=true;foreach(var reserved in partyReservedSeats)if(Vector3.Distance(reserved,p)<1)clear=false;foreach(var collider in Physics.OverlapCapsule(p+Vector3.up*.35f,p+Vector3.up*1.6f,.3f,~(1<<2),QueryTriggerInteraction.Ignore))if(collider!=Player.Body&&collider.bounds.max.y>p.y+.2f)clear=false;if(clear){partyReservedSeats.Add(p);return p;}}var fallback=c+Vector3.right*(n%4);partyReservedSeats.Add(fallback);return fallback;}
        Transform BuildPartyFlyingCar(Transform parent,Vector3 p,Color color){var o=new GameObject("宾客乘坐的飞车").transform;o.SetParent(parent,false);o.position=p;var a=o.gameObject.AddComponent<RoyalArt>();a.Piece("飞车车身",Vector3.zero,new Vector3(2.3f,.55f,3),color);a.Piece("透明座舱",Vector3.up*.55f,new Vector3(1.6f,.25f,1.3f),new Color(.65f,.86f,.94f));foreach(float x in new[]{-.9f,.9f}){a.Piece("发光悬浮轮",new Vector3(x,-.35f,0),new Vector3(.3f,.3f,2),new Color(.56f,.89f,1));a.Piece("车灯",new Vector3(x,.05f,1.55f),Vector3.one*.25f,new Color(1,.93f,.6f),PrimitiveType.Sphere);}return o;}
        void BuildPartyPropArt(Transform root,int kind)
        {
            var a=root.gameObject.AddComponent<RoyalArt>();Color dark=new Color(.1f,.12f,.2f),pink=new Color(.88f,.5f,.72f),cream=new Color(.96f,.84f,.65f);if(kind==0){a.Piece("音响箱体",new Vector3(0,.7f,0),new Vector3(.8f,1.4f,.6f),dark,PrimitiveType.Cube,true);foreach(float y in new[]{.4f,1})a.Piece("圆形扬声器",new Vector3(0,y,.34f),new Vector3(.48f,.48f,.12f),new Color(.44f,.49f,.58f),PrimitiveType.Sphere);a.Piece("音量灯",new Vector3(0,1.3f,.35f),new Vector3(.4f,.05f,.03f),new Color(.5f,1,.83f));}
            if(kind==1){a.Piece("彩光灯座",new Vector3(0,.25f,0),new Vector3(.65f,.5f,.65f),dark,PrimitiveType.Cube,true);a.Piece("柔和彩灯球",new Vector3(0,.8f,0),Vector3.one*.8f,new Color(.69f,.54f,1),PrimitiveType.Sphere);}
            if(kind==2){a.Piece("可站上的音乐舞台",new Vector3(0,.2f,0),new Vector3(3,.4f,2.3f),pink,PrimitiveType.Cube,true);for(int i=0;i<6;i++)a.Piece("舞台彩色格",new Vector3(-1+i%3,.42f,-.5f+i/3),new Vector3(.9f,.035f,.9f),Color.HSVToRGB(i*.16f,.5f,.92f));a.Piece("话筒架",new Vector3(.9f,1,0),new Vector3(.06f,1.3f,.06f),dark);a.Piece("话筒",new Vector3(.9f,1.7f,0),Vector3.one*.15f,dark,PrimitiveType.Sphere);}
            if(kind==3){a.Piece("派对点心桌",new Vector3(0,.75f,0),new Vector3(2.4f,.2f,1.5f),cream,PrimitiveType.Cube,true);foreach(float x in new[]{-.9f,.9f})a.Piece("桌腿",new Vector3(x,.35f,0),new Vector3(.18f,.7f,.18f),pink);for(int i=0;i<5;i++)a.Piece("水果蛋糕点心",new Vector3(-.8f+i*.4f,1,.2f),new Vector3(.3f,.25f,.35f),Color.HSVToRGB(i*.19f,.4f,.92f),PrimitiveType.Sphere);}
            if(kind==4)for(int i=0;i<3;i++){a.Piece("气球细绳",new Vector3((i-1)*.25f,1.2f,0),new Vector3(.02f,2.1f,.02f),cream);a.Piece("圆润彩色气球",new Vector3((i-1)*.3f,2.5f+i*.1f,0),new Vector3(.45f,.6f,.45f),Color.HSVToRGB(i*.27f,.5f,.95f),PrimitiveType.Sphere);}
            if(kind==5)BuildPortableSwing(root,a);
            if(kind==6)BuildPortableSlide(root,a);
        }
        AudioClip EnsurePartyMusic(){if(partyMelody!=null)return partyMelody;int rate=22050;float[] data=new float[rate*8];float[] notes={261.6f,329.6f,392,329.6f,349.2f,440,392,293.7f,329.6f,392,523.3f,440,349.2f,392,329.6f,261.6f};for(int i=0;i<data.Length;i++){float t=i/(float)rate,phase=t%.5f;data[i]=Mathf.Sin(2*Mathf.PI*notes[Mathf.Min(15,(int)(t*2))]*t)*.25f*Mathf.Exp(-phase*5)*Mathf.Min(1,phase*40);}partyMelody=AudioClip.Create("原创轻柔派对旋律",data.Length,1,rate,false);partyMelody.SetData(data,0);return partyMelody;}
        void TickHomeParty(float dt)
        {
            if(Paused||partyRoot==null)return;if(IsNight&&!homePartyRunning)StartHomeParty();foreach(var prop in partyRoot.GetComponentsInChildren<HomePartyPropView>())if(prop.Lamp!=null){prop.Lamp.enabled=prop.Data.on;prop.Lamp.color=Color.HSVToRGB(Mathf.Repeat(Time.time*.06f+prop.Data.id*.2f,1),.55f,1);prop.Lamp.intensity=.6f+.2f*Mathf.Sin(Time.time*2);}
            foreach(var guest in partyRoot.GetComponentsInChildren<HomePartyGuestView>()){guest.Age+=dt;if(guest.Phase==0){if(guest.Age<0)continue;float t=Mathf.SmoothStep(0,1,Mathf.Clamp01(guest.Age/8));guest.Car.position=Vector3.Lerp(guest.From,guest.Landing,t);guest.transform.position=guest.Car.position+Vector3.up*.35f;if(t>=1){guest.Phase=1;Destroy(guest.Car.gameObject);guest.Car=null;guest.transform.position=guest.Landing;}}
                else if(guest.Phase==1){var nav=NpcNavigation.Ensure(guest.transform);Vector3 target=guest.Route[Mathf.Min(guest.RouteStep,guest.Route.Count-1)];nav.MoveTo(target,2.5f,Mathf.Min(dt,.1f));if(Vector3.Distance(guest.transform.position,target)<.35f){if(guest.RouteStep<guest.Route.Count-1){guest.RouteStep++;guest.PassedDoor=true;}else{guest.Phase=2;guest.Data.arrived=true;SavePartyState();}}}
                else{guest.transform.position=guest.Seat+Vector3.up*(.15f+Mathf.Max(0,Mathf.Sin(guest.Age*.85f))*1.15f);guest.transform.rotation=Quaternion.Euler(0,180+Mathf.Sin(guest.Age*.8f)*25,0);foreach(Transform arm in guest.transform)if(arm.name=="手臂")arm.localRotation=Quaternion.Euler(Mathf.Sin(guest.Age*2.2f)*22,0,0);}}
        }
        public bool TryHomePartyG(){if(Paused||!RayFromView(out var hit,5))return false;var guest=hit.collider.GetComponentInParent<HomePartyGuestView>();if(guest!=null){partyTalker=guest;partyChatPage++;string[] lines={"谢谢你邀请我，今天晚上真开心！","这里的彩灯真漂亮，我们一起跳舞吧。","我给大家唱一首轻快的小曲！","舞台、点心和朋友，一样都不能少。"};Notice=guest.Data.name+"："+lines[partyChatPage%lines.Length];if(partyChatPage%4==2)audioSource.PlayOneShot(EnsurePartyMusic(),.12f);return true;}var prop=hit.collider.GetComponentInParent<HomePartyPropView>();if(prop==null)return false;if(prop.Data.kind==3&&prop.Data.snacks>0){prop.Data.snacks--;Health=Mathf.Min(10,Health+1);Notice="吃了一块派对点心，还剩"+prop.Data.snacks+"份。";}else if(prop.Data.kind==2){Notice="你登上了彩色舞台，宾客一起挥手跳舞。";audioSource.PlayOneShot(placeSound);}else{prop.Data.on=!prop.Data.on;if(prop.Speaker!=null){if(prop.Data.on)prop.Speaker.Play();else prop.Speaker.Stop();}Notice=PartyItemNames[prop.Data.kind]+(prop.Data.on?"已打开。":"已关闭。");}SavePartyState();return true;}
        void RestoreHomeParty(SavedWorld s){ResetHomePartyModels();partyBag=false;PutAwayPartyItem();Array.Clear(PartyStock,0,PartyStock.Length);if(s.partyStock!=null)Array.Copy(s.partyStock,PartyStock,Mathf.Min(s.partyStock.Length,PartyStock.Length));partyKitVersion=s.partyKitVersion;EnsurePartyKit();HomePartyGuests.Clear();if(s.partyGuests!=null)HomePartyGuests.AddRange(s.partyGuests);HomePartyProps.Clear();if(s.partyProps!=null)HomePartyProps.AddRange(s.partyProps);partyHome=s.partyHome??"";homePartyRunning=s.partyRunning;IsNight=s.partyNight;}
        public static void ValidateHomeParty(SavedWorld s){if(s.partyStock==null)s.partyStock=new int[7];if(s.partyStock.Length==5)Array.Resize(ref s.partyStock,7);if(s.partyStock.Length!=7||s.partyKitVersion<0||s.partyKitVersion>2)throw new System.IO.InvalidDataException("派对用品数据不合法");foreach(int n in s.partyStock)if(n<0||n>9999)throw new System.IO.InvalidDataException("派对库存不合法");if(s.partyGuests==null)s.partyGuests=new List<HomePartyGuest>();if(s.partyProps==null)s.partyProps=new List<HomePartyProp>();if(s.partyGuests.Count>100||s.partyProps.Count>100)throw new System.IO.InvalidDataException("派对记录过多");var keys=new HashSet<string>();foreach(var g in s.partyGuests)if(g==null||string.IsNullOrEmpty(g.key)||g.key.Length>200||!keys.Add(g.key)||g.kind<0||g.kind>5||g.style<0||g.style>6||g.region<0||g.region>=VoxelWorld.RegionNames.Length)throw new System.IO.InvalidDataException("派对宾客不合法");var ids=new HashSet<int>();foreach(var p in s.partyProps)if(p==null||p.id<1||!ids.Add(p.id)||p.kind<0||p.kind>6||p.region<0||p.region>=VoxelWorld.RegionNames.Length||p.snacks<0||p.snacks>12||!CameraVectorValid(p.position)||float.IsNaN(p.yaw)||float.IsInfinity(p.yaw))throw new System.IO.InvalidDataException("派对摆放不合法");}
        void DrawPartyBag(float w,float h){float x=w/2-365,y=h/2-285;Panel(new Rect(x,y,730,570),Paper);Label(new Rect(x+20,y+15,685,40),"书包 · 派对与游乐用品",27,Ink);Label(new Rect(x+20,y+65,685,50),"七种用品开局就有，不用先发邀请函。\n点击拿出 → 右键摆在自家 → G玩 / 开关 → 左键收回。",17,Muted);for(int i=0;i<PartyStock.Length;i++){Rect box=new Rect(x+20+(i%2)*348,y+134+(i/2)*84,334,74);if(FlatButton(box,PartyItemNames[i]+"  × "+PartyStock[i]+"\n拿在手里",true))TakePartyItem(i);}Label(new Rect(x+20,y+502,465,35),"已邀请"+HomePartyGuests.Count+"位；N天黑迎宾，M白天结束",16,Ink);if(GUI.Button(new Rect(x+500,y+502,205,38),"关闭 / E / Esc"))ClosePartyBag();}
    }
}
